    public List<ChatCompletionMessageToolCall> ToolCalls { get; set; }
    
    /// <summary>
    /// The role of the author of this message.
    /// </summary>
    /// <value>The role of the author of this message.</value>
    public enum RoleEnum
    {
        
        /// <summary>
        /// Enum AssistantEnum for assistant
        /// </summary>
        AssistantEnum = 1
    }

    public RoleEnum Role { get; set; }
    public ChatCompletionResponseMessageFunctionCall FunctionCall { get; set; }
    public ChatCompletionResponseMessageAudio Audio { get; set; }
}


